pub(crate) fn marker(v:&Value)->bool {crate::ability_ir::contains(v,|v|v["kind"]=="discardHandSystem"||v["kind"]=="reveal"||(v["kind"]=="abilityFactory"&&crate::ability_ir::contains(&v["body"],|v|v["kind"]=="ref"&&v["path"].as_array().is_some_and(|p|p.len()==3&&p[1]=="target"&&p[2]=="cost"))))}
