pub(crate) fn prepare(e:&Value)->Result<Option<bool>,String>{
 if !marker(&e["abilities"]){return Ok(None)}
 let fail=||Err("captured hand-cost requires complete closed ordinary source and exact physical-card continuation; unsupported continuation-context remains source-only".into());
 let allowed=["setCode","sourcePath","sourceHash","abilities","className","baseClass","id","internalName","status","card","dataHash","keywordValues","requiredCapabilities","diagnostics","attachCondition","piloting","stateWatchers","historyHelpers","privatePrograms","classMethods","privateClassConstants","inheritedSource","deploymentOverride","setupValidationOverrides"];
 if e.as_object().is_none_or(|o|o.keys().any(|k|!allowed.contains(&k.as_str())))||e["id"]!=e["card"]["id"]||e["internalName"]!=e["card"]["internalName"] {return fail()}
 if !crate::admission::SourceContextPolicy::Closed.accepts(e)||e["status"]!="supported"||!e["attachCondition"].is_null()||!e["piloting"].is_null()||e["keywordValues"]!=json!({}) {return fail()}
 for (reveal,profile,abilities,class) in [(false,PROFILE0,ABILITIES0,"EventCard"),(true,PROFILE1,ABILITIES1,"NonLeaderUnitCard")] {
 let profile:Value=serde_json::from_str(profile).unwrap();let abilities:Value=serde_json::from_str(abilities).unwrap();
 if e["className"]==if reveal {"QueenSorunaWillingToFight"}else{"RecklessSacrifice"} && e["baseClass"]==class&&e["abilities"]==abilities&&e["card"].as_object().is_some_and(|o|o.keys().all(|k|profile.get(k).is_some()||["id","internalName","setId","setCodes","pilotText","pilotBox","pilotingBox","deployCost"].contains(&k.as_str())))&&profile.as_object().unwrap().iter().all(|(k,v)|e["card"][k]==*v)&&["pilotText","pilotBox","pilotingBox","deployCost"].iter().all(|k|e["card"][k].is_null()) {return Ok(Some(reveal))}
 } fail()
}
pub(crate) fn programs(e:&Value,reveal:bool,start:u16)->Result<(CardPrograms,Vec<Program>),String>{
 start.checked_add(if reveal{2}else{1}).ok_or("physical hand-cost program reservation exceeds stored program+1 capacity")?;
 let triggers=if reveal {vec!["whenPlayed","onAttack"]}else{vec!["event"]};let mut programs=Vec::new();let mut ids=Vec::new();
 for trigger in triggers {ids.push(start+programs.len() as u16);programs.push(Program{attached_host:false,piloting_ability:false,pilot_unit_ability:false,hooks:vec![],gained_host:None,attached_context:None,title:e["abilities"]["card"][0]["title"].as_str().unwrap().into(),context_title:vec![],trigger:trigger.into(),attacker_must_survive:false,coordinate:false,costs:vec![],optional:false,requires_confirmation:false,condition:None,instructions:if reveal {vec![Instruction::HandCost{reveal,stage:0},Instruction::HandCost{reveal,stage:1},Instruction::HandCost{reveal,stage:2},Instruction::EndStep]}else{vec![Instruction::HandCost{reveal,stage:0},Instruction::HandCost{reveal,stage:2},Instruction::EndStep]},event_end:if reveal{4}else{3},executable:Err("physical hand cost pending compilation"),select_ends:vec![]});}
 Ok((CardPrograms{card:ids,..CardPrograms::default()},programs))
}

/// Lossless model physical identity: MAX_CARDS=256, valid identities1..255.
/// Dedicated newtype; zero is absence, never a truncated u16.
#[derive(Debug,Clone,Copy,Default,PartialEq,Eq)]
#[repr(transparent)]
pub struct PhysicalHandCard(u8);
impl PhysicalHandCard {
 pub fn capture(id:u16)->Result<Self,String>{if id==0 {return Err("missing physical hand card".into())}u8::try_from(id).map(Self).map_err(|_|"physical hand card exceeds model capacity".into())}
 pub fn id(self)->u16 {u16::from(self.0)}
}

/// Absence of mutable printed attributes is an executable invariant of this
/// native graph, required for retaining a physical identity rather than a scalar.
/// Bound every raw entry/card scan before dropping metadata.
pub(crate) fn reject_printed_override(value:&Value)->Result<(),String>{
 let mut stack=vec![(value,0usize)];let mut nodes=0usize;
 while let Some((v,depth))=stack.pop(){nodes+=1;if depth>128||nodes>100_000{return Err("printed-cost provenance scan exceeds bounds".into())}
 if v["effectType"]=="printedAttributesOverride"||v["kind"]=="overridePrintedAttributes"||v.as_object().is_some_and(|o|o.get("printedAttributesOverride").is_some_and(|v|!v.is_null())) {return Err("mutable printed attributes are unsupported in native card graph".into())}
 let children=match v {Value::Object(o)=>o.len(),Value::Array(a)=>a.len(),_=>0};if children>100_000usize.saturating_sub(nodes+stack.len()){return Err("printed-cost provenance scan exceeds bounds".into())}
 match v {Value::Object(o)=>stack.extend(o.values().map(|v|(v,depth+1))),Value::Array(a)=>stack.extend(a.iter().map(|v|(v,depth+1))),_=>{}}
 }Ok(())
}
